Section GEN.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (v88 v96 v120 : word).
  Variables (m : fmem) (DT SY WK cons T nbb wEnd minW mwr e1 len1 : Z) (sorted : list (option Z)) (js jt : list byte)
    (ncells : nat) (rs0 rv : list Z).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 4 * Z.of_nat ncells <= 2^47.
  Hypothesis HSYE : SY = WK + 736.
  Hypothesis HWK : 0 < WK /\ WK + 2124 <= 2^47.
  Hypothesis DJ : DT + 4 + 4 * Z.of_nat ncells <= WK \/ WK + 2124 <= DT + 4.
  Hypothesis HSP : DT + 4 + 4 * Z.of_nat ncells <= SP /\ WK + 2124 <= SP /\ SP + 272 <= 2^47.
  Hypothesis HT : 1 <= T <= 12.
  Hypothesis HNBB : 2 <= nbb <= 13.
  Hypothesis HWE : 2 <= wEnd <= nbb.
  Hypothesis HCONS : 1 <= cons <= 11.
  Hypothesis HMW : minW = Z.max 1 mwr /\ mwr = cons + nbb - T /\ minW < wEnd.
  Hypothesis HLEN : len1 = 2 ^ (T - cons) /\ 1 <= T - cons <= 11.
  Hypothesis HE1 : e1 <= 256.
  Hypothesis LRS : length rs0 = 15%nat.
  Hypothesis HRSV : forall w, 1 <= w <= wEnd - 1 -> 0 <= Znth w rs0 <= Znth (w + 1) rs0 /\ Znth (w + 1) rs0 <= 256.
  Hypothesis LRV : length rv = 156%nat.
  Variable PRV : Z -> Prop.
  Hypothesis HPRV : forall w, minW <= w <= wEnd - 1 -> PRV (rv_idx cons w).
  Hypothesis HRVR : forall w, minW <= w <= wEnd - 1 -> 0 <= Znth (rv_idx cons w) rv < 2^31.
  Hypothesis RSA0 : u32arr psegs m (WK + 676) (map (Z_to_bv 64) rs0).
  Hypothesis RVA0 : rv_at m WK rv PRV.
  Hypothesis FR0 : rw_cells psegs m (SP + 72)
    [C8 (Z_to_bv 64 (DT + 52)); C8 (Z_to_bv 64 (DT + 20)); C8 v88; C8 v96; C8 (Z_to_bv 64 nbb);
     C8 (Z_to_bv 64 (WK + 52 * cons + 4 * minW)); C8 v120; C8 (Z_to_bv 64 e1); C8 (Z_to_bv 64 (cons * 65536 + 16777216));
     C8 (Z_to_bv 64 mwr); C8 (Z_to_bv 64 (DT + 4))].
  Notation INV m1 dt := (x2f_inv m m1 DT SY js jt sorted ncells dt).
  Notation D1 := (cons * 65536 + 16777216).

  Lemma gen_loop : forall f s dt start m1 r (x8 x9 x10 x12 x13 x14 x17 x21 x22 x25 x28 x29 : word),
    fill_two_level f dt s e1 start len1 T cons minW wEnd rv sorted rs0 nbb = Ok r ->
    Z.of_nat f = e1 - s + 1 -> 0 <= s < e1 -> 0 <= start -> start + len1 * (e1 - s) <= 4096 -> INV m1 dt ->
    (forall m2 dt' (y1 y5 y7 y8 y9 y10 y11 y12 y13 y14 y16 y17 y21 y22 y25 y26 y27 y28 y29 : word),
       r = dt' -> INV m2 dt' ->
       evt psegs POST (MS (mkR y1 sp gp tp y5 (Z_to_bv 64 wEnd) y7 y8 y9 y10 y11 y12 y13 y14 (Z_to_bv 64 (WK + 676)) y16 y17 (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8) y21 y22 (Z_to_bv 64 T) (Z_to_bv 64 SY) y25 y26 y27 y28 y29 (Z_to_bv 64 1) (Z_to_bv 64 3))
                          F (Z_to_bv 64 0x13d00) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR (Z_to_bv 64 start) sp gp tp (Z_to_bv 64 minW) (Z_to_bv 64 wEnd) (Z_to_bv 64 (WK + 52 * cons)) x8 x9 x10 (Z_to_bv 64 len1) x12 x13 x14 (Z_to_bv 64 (WK + 676)) (Z_to_bv 64 (cons + nbb)) x17 (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8) x21 x22 (Z_to_bv 64 T) (Z_to_bv 64 SY) x25 (Z_to_bv 64 e1) (Z_to_bv 64 s) x28 x29 (Z_to_bv 64 1) (Z_to_bv 64 3))
                       F (Z_to_bv 64 0x13fbc) fc None m1 (seg_rom psegs)).
